public class FindDivisible {
    public static void main(String[] args) {
        for (int n = 100; n <= 200; n++) {
            if (n % 7 == 0 && n % 11 == 0) {
                System.out.println("First number divisible by 7 and 11: " + n);
                break;  // Stop at first match
            }
        }
    }
}
// LCM(7,11) = 77. Multiples of 77: 77, 154, 231...
// Output: First number divisible by 7 and 11: 154
// break ensures we stop after finding the FIRST match — without break, all matches would print.

